const upsertRSSState = `-- name: UpsertRSSState :exec
INSERT INTO rss_state (indexer_id, last_guid, last_pub_at, last_sync_at)
VALUES (?1, ?2, ?3, ?4)
ON CONFLICT (indexer_id) DO UPDATE SET
    last_guid    = excluded.last_guid,
    last_pub_at  = excluded.last_pub_at,
    last_sync_at = excluded.last_sync_at
`

type UpsertRSSStateParams struct {
	IndexerID  int64   `json:"indexerId"`
	LastGuid   *string `json:"lastGuid"`
	LastPubAt  *int64  `json:"lastPubAt"`
	LastSyncAt *int64  `json:"lastSyncAt"`
}

func (q *Queries) UpsertRSSState(ctx context.Context, arg UpsertRSSStateParams) error {
	_, err := q.exec(ctx, q.upsertRSSStateStmt, upsertRSSState,
		arg.IndexerID,
		arg.LastGuid,
		arg.LastPubAt,
		arg.LastSyncAt,
	)
	return err
}
